-- A VERBOSE subplan's target list names the enclosing query's columns as
-- the deparser does, and a COALESCE over a domain shows the relabel to the
-- domain's base type.
CREATE DOMAIN d902 AS integer;
CREATE TABLE t902 (a integer, b d902, c text);
CREATE TABLE u902 (x integer, y d902);
INSERT INTO t902 VALUES (1, 2, 'x'), (2, NULL, 'y');
INSERT INTO u902 VALUES (1, 5), (2, 6);
ANALYZE t902;
ANALYZE u902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT (SELECT t902.a + 1 FROM u902 LIMIT 1) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a, (SELECT max(y) + t902.a FROM u902) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a, (SELECT upper(t902.c) || x::text FROM u902 WHERE x = t902.a) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT COALESCE(b, 0) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT COALESCE(b, a) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT GREATEST(b, 3), LEAST(a, b) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT NULLIF(b, 2) FROM t902;
EXPLAIN (VERBOSE, COSTS OFF) SELECT COALESCE(b, b) FROM t902;
